    const pts = Array.isArray(k.boost) ? k.boost : []; if (!pts.length) { ctx.fillStyle = '#9fb0cf'; ctx.font = '13px ' + MONO; ctx.fillText('no real points for this knot', 16, H / 2); return; }
    const vals = pts.map(([x, vv]) => { const s = Math.exp(x), X = s + 1 / s, Z = s * s + 1 / (s * s) - vv; return [x, 2 * X * X + Z * Z - X * X * Z - 2]; });
    const xs = vals.map((q) => q[0]), ys = vals.map((q) => q[1]);
    const x0 = Math.min(...xs), x1 = Math.max(...xs); const y0 = Math.max(-6, Math.min(-2.5, ...ys)), y1 = Math.min(Math.max(2.5, ...ys), 10);
    const X = (x) => 44 + (W - 56) * (x - x0) / Math.max(1e-9, x1 - x0), Y = (y) => H - 24 - (H - 36) * (clamp(y, y0, y1) - y0) / (y1 - y0);
    ctx.strokeStyle = '#2b3c6b'; ctx.lineWidth = 1; ctx.strokeRect(44, 12, W - 56, H - 36);
    ctx.setLineDash([4, 4]); ctx.strokeStyle = '#ffb547';
    [-2, 2].forEach((yy) => { ctx.beginPath(); ctx.moveTo(44, Y(yy)); ctx.lineTo(W - 12, Y(yy)); ctx.stroke(); });
    ctx.setLineDash([]);
    vals.forEach(([x, y], j) => { ctx.fillStyle = Math.abs(y) < 2 ? '#ff6f91' : '#7cc4ff'; ctx.globalAlpha = (y > y1 || y < y0) ? 0.35 : 1; ctx.beginPath(); ctx.arc(X(x), Y(y), j === i ? 5 : 2.2, 0, 2 * PI); ctx.fill(); ctx.globalAlpha = 1; if (j === i) { ctx.strokeStyle = '#ffffff'; ctx.lineWidth = 1.5; ctx.stroke(); } });
    ctx.fillText(fmt(y1, 0), 18, Y(y1) + 10); if (Math.max(...ys) > y1) ctx.fillText('values above ' + fmt(y1, 0) + ' drawn faint at the top', W - 290, 24);
    ctx.fillStyle = '#9fb0cf'; ctx.font = '11px ' + MONO;
    ctx.fillText('tr[a,b]', 50, 24); ctx.fillText('+2', 18, Y(2) + 4); ctx.fillText('−2', 18, Y(-2) + 4);
    ctx.fillText('x = log|M|  ' + fmt(x0, 2) + ' … ' + fmt(x1, 2) + '   (rose: rotation, blue: boost)', 50, H - 7);
