/* ---------- selection, panel, routing ---------- */
const sel_el = $('knot-select');
KNOTS.forEach((k, i) => { const o = document.createElement('option'); o.value = String(i); o.textContent = nameText(k.name); sel_el.appendChild(o); });

function updateCommon() {
  const k = KNOTS[sel];
  $('p-name').innerHTML = nameHTML(k.name);
  const bits = [];
  if (Number.isFinite(k.p) && Number.isFinite(k.q)) bits.push('two-bridge code ' + k.p + '/' + k.q);
  bits.push((k.volume > 0 ? 'hyperbolic' : 'torus knot'));
  $('p-sub').textContent = bits.join(' · ');
  $('p-cross').textContent = String(k.crossings);
  $('p-alex').innerHTML = polyHTML(k.alexander);
  $('p-vol').textContent = k.volume > 0 ? fmt(k.volume, 6) : '0 (not hyperbolic)';
  $('knot-count').textContent = (sel + 1) + ' of ' + KNOTS.length;
  sel_el.value = String(sel);
}
const builtFor = {};
function refreshActive() {
  if (!activeName) return;
  const v = views[activeName];
  updateCommon();
  if (builtFor[activeName] !== sel) { v.build(KNOTS[sel]); builtFor[activeName] = sel; }
  v.panel(KNOTS[sel]);
  dirty = true;
}
function setSel(i) {
  sel = ((i % KNOTS.length) + KNOTS.length) % KNOTS.length;
  refreshActive();
}
sel_el.addEventListener('change', () => setSel(parseInt(sel_el.value, 10)));
$('knot-prev').addEventListener('click', () => setSel(sel - 1));
$('knot-next').addEventListener('click', () => setSel(sel + 1));

const NAMES = ['knots', 'torus', 'stack', 'ball', 'peel', 'comm'];
const HINTS = {
  knots: 'drag to orbit · scroll or pinch to zoom · right-drag to pan',
  torus: 'drag to orbit · scroll or pinch to zoom · right-drag to pan',
  stack: 'front layer is the smallest volume · drag to orbit',
  ball: 'drag to orbit · scroll or pinch to zoom',
  peel: 'true hyperbolic distances · drag to orbit · scroll to zoom',
  comm: 'the i–k plane is the Smith disk · drag to orbit · scroll to zoom',
};
function setView(name) {
  if (!NAMES.includes(name)) name = 'knots';
  if (name === activeName) return;
  if (activeName) {
    views[activeName].exit();
    if (controls) camStates[activeName] = { pos: camera.position.clone(), tgt: controls.target.clone() };
  }
  activeName = name;
  const v = views[name];
  NAMES.forEach((n) => {
    const t = $('tab-' + n);
    if (n === name) t.setAttribute('aria-current', 'page'); else t.removeAttribute('aria-current');
    $('controls-' + n).hidden = n !== name; $('sec-' + n).hidden = n !== name;
  });
  $('stage-hint').textContent = HINTS[name];
  v.enter();
  if (controls) {
    const st = camStates[name];
    if (st) { camera.position.copy(st.pos); controls.target.copy(st.tgt); controls.update(); } else fitCamera(v);
  }
  refreshActive();
}
function route() {
  const h = (location.hash || '').replace(/^#/, '').toLowerCase();
  setView(NAMES.includes(h) ? h : 'knots');
}
window.addEventListener('hashchange', route);
$('tabs').addEventListener('click', (e) => {
  const a = e.target.closest('a'); if (!a) return;
  const h = a.getAttribute('href').slice(1);
  if (location.hash !== '#' + h) { try { location.hash = h; } catch (err) { /* sandboxed */ } }
  setView(h);
  e.preventDefault();
});
$('reset-view').addEventListener('click', () => { if (controls && activeName) fitCamera(views[activeName]); });
$('autorotate').checked = !REDUCED;
$('autorotate').addEventListener('change', (e) => { if (controls && activeName === 'knots') controls.autoRotate = e.target.checked; dirty = true; });
$('torus-labels').addEventListener('change', (e) => views.torus.setLabels(e.target.checked));

/* ---------- loop ---------- */
function tick() {
  requestAnimationFrame(tick);
  if (!renderer || !activeName) return;
  const changed = controls.update();
  if (changed || dirty) { dirty = false; renderer.render(views[activeName].scene, camera); }
}
resize();
route();
if (document.fonts && document.fonts.ready) document.fonts.ready.then(() => {
  // labels are canvas textures: rebuild once webfonts have arrived
  builtFor.torus = builtFor.stack = null; refreshActive();
});
tick();
window.__atlas = { setSel, setView, get sel() { return sel; }, get view() { return activeName; } };
